        if (offset >= 256) {
            revert OutOfBounds();
        }


        if (!(bitLength >= 1 && bitLength <= Math.min(255, 256 - offset))) {
            revert OutOfBounds();
        }


        if (value >= 0) {


            if (value >> (bitLength - 1) != 0) {
